record.field:
{
  "type": "object",
  "title": "CopyGenericTemplateRequest",
  "properties": {
    "name": {"type": "string", "example": "Landing Padrão (Minha Imobiliária)", "description": "Optional — defaults to the generic template's own name"}
  }
}

{
  "type": "object",
  "title": "GenericTemplateCopyResponse",
  "properties": {
    "id": {"type": "integer", "example": 43, "description": "New company-scoped CMS Template id"},
    "name": {"type": "string", "example": "seed_generic_landing (2)"},
    "category": {"type": "string", "enum": ["landing", "property", "about"]},
    "active": {"type": "boolean"},
    "company_id": {"type": "integer", "example": 5},
    "source_generic_template_id": {"type": "integer", "example": 46},
    "content": {"type": "string", "description": "Puck JSON content, copied from the generic template"},
    "created_at": {"type": "string", "format": "date-time"},
    "updated_at": {"type": "string", "format": "date-time"}
  }
}

{
  "type": "object",
  "title": "UpdateSettingsRequest",
  "properties": {
    "company_slug": {"type": "string", "example": "minha-agencia", "pattern": "^[a-z0-9][a-z0-9-]*$"},
    "og_default_title": {"type": "string"},
    "og_default_description": {"type": "string"},
    "custom_css": {"type": "string", "description": "Max 64KB. CSS injection patterns are blocked."},
    "custom_js": {"type": "string", "description": "Owner only. Audit fields are auto-filled."}
  }
}

{
  "type": "object",
  "title": "PublicPropertyListResponse",
  "properties": {
    "company_slug": {"type": "string", "example": "minha-agencia"},
    "count": {"type": "integer", "example": 2},
    "limit": {"type": "integer", "example": 20},
    "filters": {
      "type": "object",
      "properties": {
        "status": {"type": "array", "items": {"type": "string"}, "nullable": true, "example": ["available"]},
        "ids": {"type": "array", "items": {"type": "integer"}, "nullable": true},
        "sort": {"type": "string", "example": "newest"}
      }
    },
    "data": {
      "type": "array",
      "items": {
        "type": "object",
        "title": "PublicPropertyResponse",
        "properties": {
          "id": {"type": "integer", "example": 42},
          "reference_code": {"type": "string", "nullable": true, "example": "REF-042"},
          "name": {"type": "string", "example": "Apartamento 2 quartos"},
          "property_status": {"type": "string", "example": "available"},
          "for_sale": {"type": "boolean", "example": true},
          "for_rent": {"type": "boolean", "example": false},
          "price": {"type": "number", "example": 300000.0},
          "rent_price": {"type": "number", "example": 0.0},
          "currency": {
            "type": "object",
            "nullable": true,
            "properties": {
              "id": {"type": "integer"},
              "name": {"type": "string", "example": "BRL"},
              "symbol": {"type": "string", "example": "R$"}
            }
          },
          "area": {"type": "number", "example": 80.0},
          "num_rooms": {"type": "integer", "example": 2},
          "num_bathrooms": {"type": "integer", "example": 1},
          "num_parking": {"type": "integer", "example": 1},
          "city": {"type": "string", "example": "Sao Paulo"},
          "neighborhood": {"type": "string", "example": "Bela Vista"},
          "state": {
            "type": "object",
            "nullable": true,
            "properties": {
              "id": {"type": "integer"},
              "name": {"type": "string", "example": "Sao Paulo"},
              "code": {"type": "string", "example": "SP"}
            }
          },
          "property_type": {
            "type": "object",
            "nullable": true,
            "properties": {
              "id": {"type": "integer"},
              "name": {"type": "string", "example": "Apartamento"}
            }
          },
          "image_url": {"type": "string", "nullable": true, "example": "/api/v1/public/properties/minha-agencia/42/image"},
          "description_short": {"type": "string", "nullable": true},
          "create_date": {"type": "string", "format": "date-time", "nullable": true}
        }
      }
    },
    "_links": {
      "type": "object",
      "properties": {
        "self": {"type": "string", "example": "/api/v1/public/properties/minha-agencia?sort=newest&limit=20"}
      }
    }
  }
}
